<?php
declare(strict_types=1);
header('X-Content-Type-Options: nosniff');
header('Permissions-Policy: microphone=(self)');

$logFile = __DIR__ . '/piano_debug.log';
if (isset($_GET['diag'])) {
    $action = (string)$_GET['diag'];
    if ($action === 'append') {
        header('Content-Type: application/json; charset=utf-8');
        $raw = file_get_contents('php://input') ?: '';
        $p = json_decode($raw, true);
        if (!is_array($p)) { http_response_code(400); echo '{"ok":false}'; exit; }
        $session = preg_replace('/[^a-zA-Z0-9._-]/', '', (string)($p['session'] ?? 'unknown')) ?: 'unknown';
        $events = is_array($p['events'] ?? null) ? array_slice($p['events'], 0, 100) : [];
        if (is_file($logFile) && (filesize($logFile) ?: 0) > 5*1024*1024) @rename($logFile, __DIR__.'/piano_debug.previous.log');
        $fh = @fopen($logFile, 'ab');
        if (!$fh) { http_response_code(500); echo json_encode(['ok'=>false,'error'=>'log not writable']); exit; }
        flock($fh, LOCK_EX);
        foreach ($events as $e) {
            if (!is_array($e)) continue;
            fwrite($fh, json_encode([
                'server_time'=>gmdate('c'),'session'=>$session,
                'client_time'=>(string)($e['time']??''),'level'=>(string)($e['level']??'info'),
                'event'=>(string)($e['event']??'event'),'data'=>$e['data']??null
            ], JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR)."\n");
        }
        fflush($fh); flock($fh, LOCK_UN); fclose($fh); echo '{"ok":true}'; exit;
    }
    if ($action === 'report') {
        header('Content-Type: text/plain; charset=utf-8'); header('Cache-Control: no-store');
        $session = preg_replace('/[^a-zA-Z0-9._-]/', '', (string)($_GET['session']??''));
        echo "LEARNPIANO DIAGNOSTIC REPORT\nPHP: ".PHP_VERSION."\nHTTPS: ".((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'yes':'no')."\nSession: ".($session?:'all')."\n".str_repeat('=',68)."\n";
        if (is_file($logFile)) foreach (array_slice(file($logFile, FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[], -1200) as $line) {
            $r=json_decode($line,true); if(!is_array($r)||($session!==''&&($r['session']??'')!==$session)) continue;
            echo '['.($r['client_time']?:$r['server_time']??'').'] '.strtoupper((string)($r['level']??'info')).' '.($r['event']??'event')."\n";
            if (($r['data']??null)!==null) echo '  '.str_replace("\n","\n  ",json_encode($r['data'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_PARTIAL_OUTPUT_ON_ERROR))."\n";
        }
        exit;
    }
}

$demoFile = __DIR__ . '/demo.musicxml';
$demoUrl = 'https://raw.githubusercontent.com/aortega/note-wise/efb65368e23f8c72a66352e393497d33fcb1c2c2/android/samples/xmlsamples/Clair_de_Lune__Debussy.musicxml';
if (!is_file($demoFile) || (filesize($demoFile) ?: 0) < 50000) {
    $ctx = stream_context_create(['http'=>['timeout'=>12,'header'=>"User-Agent: LearnPiano/1.0\r\n"],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);
    $xml = @file_get_contents($demoUrl, false, $ctx);
    if (is_string($xml) && strlen($xml)>50000 && stripos($xml,'Clair de Lune')!==false) @file_put_contents($demoFile,$xml,LOCK_EX);
}
