var(--kbH) + 8px);z-index:9;display:flex;gap:7px;align-items:center;background:#05090dcc;border:1px solid #203142;border-radius:8px;padding:5px 7px}#scrub{width:100%}#timeText{min-width:80px;text-align:right;font-size:11px;color:#b4c7d8}.rz{position:absolute;z-index:40;touch-action:none}.n{left:14px;right:14px;top:0;height:9px;cursor:ns-resize}.s{left:14px;right:14px;bottom:0;height:11px;cursor:ns-resize}.e{right:0;top:14px;bottom:14px;width:11px;cursor:ew-resize}.w{left:0;top:14px;bottom:14px;width:11px;cursor:ew-resize}.ne{right:0;top:0;width:20px;height:20px;cursor:nesw-resize}.nw{left:0;top:0;width:20px;height:20px;cursor:nwse-resize}.se{right:0;bottom:0;width:26px;height:26px;cursor:nwse-resize;background:linear-gradient(135deg,transparent 50%,#7795af 51% 58%,transparent 59% 67%,#7795af 68% 75%,transparent 76%)}.sw{left:0;bottom:0;width:20px;height:20px;cursor:nesw-resize}#focusClose{display:none;position:absolute;right:14px;top:14px;z-index:100;width:46px;height:46px;border-radius:50%;background:#03080cdd;color:white;font-size:28px;border:1px solid #fff6}.focus .topbar,.focus #status,.focus #help{display:none!important}.focus #workspace{position:fixed;inset:0;z-index:9999;width:100vw!important;height:100vh!important;background:#05090d}.focus #trainer{left:var(--calLeft,0px)!important;top:0!important;width:var(--calWidth,100%)!important;height:100%!important;--kbH:var(--calKbH,132px);min-width:0;min-height:0;border:0;border-radius:0;box-shadow:none}.focus #dragbar,.focus #hud,.focus #scrubWrap,.focus .rz{display:none!important}.focus #fallWrap{top:0}.focus #focusClose{display:flex;align-items:center;justify-content:center}.focus.force-landscape #workspace{left:100vw!important;width:100vh!important;height:100vw!important;transform:rotate(90deg);transform-origin:top left}.focus.force-landscape #trainer{max-width:none!important}@media(max-width:760px){.topbar{gap:6px}.ctrl .lbl{display:none}#help{display:none}:root{--kbH:108px}#trainer{left:2%;width:96%;top:10px;h