(()=>{'use strict';
const $=id=>document.getElementById(id),trainer=$('trainer'),workspace=$('workspace'),drag=$('dragbar'),canvas=$('fallCanvas'),ctx=canvas.getContext('2d'),fall=$('fallWrap'),keyboard=$('keyboard'),playB=$('play'),restartB=$('restart'),file=$('file'),tempo=$('tempo'),lead=$('lead'),view=$('view'),soundB=$('sound'),testB=$('test'),listenB=$('listen'),micB=$('mic'),heardB=$('heard'),matchB=$('match'),diagB=$('diag'),fullB=$('full'),closeB=$('focusClose'),status=$('status'),title=$('title'),count=$('count'),now=$('now'),scrub=$('scrub'),timeText=$('timeText'),sens=$('sens'),conf=$('conf'),a4=$('a4');
const S='piano-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),diagQ=[];let diagTimer=0;function d(level,event,data={}){diagQ.push({time:new Date().toISOString(),level,event,data});if(!diagTimer)diagTimer=setTimeout(flush,800)}async function flush(){clearTimeout(diagTimer);diagTimer=0;if(!diagQ.length)return;const events=diagQ.splice(0,100);try{await fetch(location.pathname+'?diag=append',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:S,events}),keepalive:true})}catch(_){diagQ.unshift(...events)}}window.addEventListener('error',e=>d('error','window_error',{message:e.message,line:e.lineno,col:e.colno}));window.addEventListener('unhandledrejection',e=>d('error','promise_rejection',{reason:String(e.reason)}));
const N=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'],BLACK=new Set([1,3,6,8,10]),name=m=>N[((m%12)+12)%12]+(Math.floor(m/12)-1),isBlack=m=>BLACK.has(((m%12)+12)%12),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let score={title:'No score',notes:[],bpm:66,total:0},beat=0,playing=false,startBeat=0,startTime=0,lastAudio=-.001,raf=0,keyEls=new Map(),geom=new Map(),vmin=36,vmax=96,target=new Set();
function setStatus(s,bad=false){status.textContent=s;status.style.color=bad?'#ff8f99':'#9fb3c5'}
function parseXML(txt,label='score'){const x=new DOMParser().parseFromString(txt,'application/xml');if(x.querySelector('parsererror'))throw Error('Invalid MusicXML');const p=x.querySelector('part');if(!p)throw Error('No piano part');let div=1,bpm=66,base=0,notes=[];const wt=x.querySelector('work-title,movement-title')?.textContent?.trim(),composer=x.querySelector('creator[type="composer"]')?.textContent?.trim();for(const m of p.querySelectorAll('measure')){let cur=0,last=0,max=0;for(const c of m.children){if(c.tagName==='attributes'){const q=c.querySelector('divisions');if(q)div=Math.max(1,+q.textContent||1)}else if(c.tagName==='direction'){const q=c.querySelector('sound[tempo]');if(q&&+q.getAttribute('tempo'))bpm=+q.getAttribute('tempo')}else if(c.tagName==='backup')cur-=+(c.querySelector('duration')?.textContent||0)/div;else if(c.tagName==='forward')cur+=+(c.querySelector('duration')?.textContent||0)/div;else if(c.tagName==='note'){const dur=+(c.querySelector('duration')?.textContent||0)/div,ch=!!c.querySelector('chord'),st=ch?last:base+cur;if(!ch)last=st;const pitch=c.querySelector('pitch');if(pitch){const step=pitch.querySelector('step')?.textContent||'C',alt=+(pitch.querySelector('alter')?.textContent||0),oct=+(pitch.querySelector('octave')?.textContent||4),pc={C:0,D:2,E:4,F:5,G:7,A:9,B:11}[step]+alt,midi=(oct+1)*12+pc;if(midi>=21&&midi<=108)notes.push({m:midi,s:st,d:Math.max(.05,dur),staff:+(c.querySelector('staff')?.textContent||1),v:.76})}if(!ch)cur+=dur;max=Math.max(max,cur,st-base+dur)}}base+=Math.max(max,1)}if(!notes.length)throw Error('No pitched notes');const total=Math.max(...notes.map(n=>n.s+n.d));return{title:[wt,composer].filter(Boolean).join(' — ')||label,notes,bpm:(bpm===120&&/clair de lune/i.test(wt||''))?66:bpm,total}}
