function apply(s,label){pause();score=s;tempo.value=Math.round(s.bpm||66);$('tempoV').textContent=tempo.value;beat=0;title.textContent=s.title;count.textContent=s.notes.length+' notes';$('fileInfo').textContent=label;updateRange();buildKeys();resize();updateScrub();draw();preload();setStatus('Loaded '+s.title+' — '+s.notes.length+' notes.')}
function updateRange(){if(!score.notes.length){vmin=36;vmax=96;return}const lo=Math.min(...score.notes.map(n=>n.m)),hi=Math.max(...score.notes.map(n=>n.m));if(view.value==='88'){vmin=21;vmax=108}else if(view.value==='61'){vmin=36;vmax=96;if(lo<vmin||hi>vmax){const c=Math.round((lo+hi)/2);vmin=clamp(c-30,21,48);vmax=vmin+60}}else{vmin=clamp(lo-3,21,108);vmax=clamp(hi+3,21,108);while(vmin>21&&vmin%12)vmin--;while(vmax<108&&vmax%12)vmax++}}
function buildKeys(){keyboard.innerHTML='';keyEls.clear();geom.clear();let all=[];for(let m=vmin;m<=vmax;m++)all.push(m);const whites=all.filter(m=>!isBlack(m)),ww=100/whites.length,idx=new Map();whites.forEach((m,i)=>idx.set(m,i));for(const m of whites){let k=document.createElement('div');k.className='key white';k.dataset.m=m;k.style.left=(idx.get(m)*ww)+'%';k.style.width=ww+'%';if(m%12===0)k.textContent=name(m);keyboard.append(k);keyEls.set(m,k);geom.set(m,{x:idx.get(m)*ww,w:ww,b:0})}for(const m of all.filter(isBlack)){let prev=m-1;while(prev>=vmin&&isBlack(prev))prev--;if(!idx.has(prev))continue;let boundary=(idx.get(prev)+1)*ww,bw=ww*.62,k=document.createElement('div');k.className='key black';k.dataset.m=m;k.style.left=(boundary-bw/2)+'%';k.style.width=bw+'%';keyboard.append(k);keyEls.set(m,k);geom.set(m,{x:boundary-bw/2,w:bw,b:1})}if(lastMidi!==null)keyEls.get(lastMidi)?.classList.add('heard')}
function resize(){const r=fall.getBoundingClientRect(),dp=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*dp));canvas.height=Math.max(1,Math.round(r.height*dp));canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(dp,0,0,dp,0,0);draw()}
function draw(){const r=fall.getBoundingClientRect(),w=r.width,h=r.height;if(w<=0||h<=0)return;ctx.fillStyle='#05090d';ctx.fillRect(0,0,w,h);const L=+lead.value;for(const [m,g]of geom){let x=g.x/100*w;ctx.strokeStyle='rgba(255,255,255,.03)';ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let b=Math.floor(beat);b<=beat+L+1;b++){let y=h-((b-beat)/L)*h;ctx.strokeStyle=b%4===0?'#79a5c62c':'#79a5c612';ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let active=new Set();for(const n of score.notes){let end=n.s+n.d;if(end<beat-.1||n.s>beat+L+.5)continue;let g=geom.get(n.m);if(!g)continue;let x=g.x/100*w+1,nw=Math.max(2,g.w/100*w-2),yb=h-((n.s-beat)/L)*h,nh=Math.max(8,n.d/L*h),yt=yb-nh,on=beat>=n.s&&beat<end;if(on)active.add(n.m);ctx.fillStyle=n.staff===2?(on?'#5aaeff':'#438fde'):(on?'#5ff191':'#41cd74');ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,yt,nw,nh,Math.min(6,nw/3));else ctx.rect(x,yt,nw,nh);ctx.fill()}target=active;for(const[m,k]of keyEls){k.classList.toggle('active',active.has(m));if(m===lastMidi)k.classList.add('heard')}now.textContent=active.size?[...active].sort((a,b)=>a-b).map(name).join(' '):(playing?'Listening ahead…':'Ready');matchUpdate()}
const spb=()=>60/(+tempo.value||66),seconds=()=>score.total*spb();function updateScrub(){scrub.max=Math.max(.001,score.total);scrub.value=beat;timeText.textContent=(beat*spb()).toFixed(1)+' / '+seconds().toFixed(1)+'s'}function seek(b){beat=clamp(+b||0,0,score.total);lastAudio=beat;if(playing){startBeat=beat;startTime=performance.now()}updateScrub();draw()}
let AC=null,master=null,buffers=new Map(),loads=new Map(),soundOn=true,activeSources=new Set();const roots=[[21,'A0.mp3'],[24,'C1.mp3'],[30,'Fs1.mp3'],[36,'C2.mp3'],[42,'Fs2.mp3'],[48,'C3.mp3'],[54,'Fs3.mp3'],[60,'C4.mp3'],[66,'Fs4.mp3'],[69,'A4.mp3'],[72,'C5.mp3'],[78,'Fs5.mp3'],[84,'C6.mp3'],[90,'Fs6.mp3'],[96,'C7.mp3'],[102,'Fs7.mp3'],[108,'C8.mp3']];function audio(){if(!AC){AC=new(window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=.78;master.connect(AC.destination);d('info','audio_created',{rate:AC.sampleRate})}if(AC.state==='suspended')AC.resume();return AC}function nearest(m){return roots.reduce((a,b)=>Math.abs(b[0]-m)<Math.abs(a[0]-m)?b:a)}async function loadRoot(r,f){if(buffers.has(r))return buffers.get(r);if(loads.has(r))return loads.get(r);let p=(async()=>{let a=audio(),res=await fetch('https://tonejs.github.io/audio/salamander/'+f,{cache:'force-cache'});if(!res.ok)throw Error('sample '+res.status);let b=await a.decodeAudioData(await res.arrayBuffer());buffers.set(r,b);return b})();loads.set(r,p);try{return await p}finally{loads.delete(r)}}function synth(m,dur=.7,v=.75){let a=audio(),t=a.currentTime,f=440*Math.pow(2,(m-69)/12),g=a.createGain(),o=a.createOscillator(),o2=a.createOscillator();o.type='triangle';o2.type='sine';o.frequency.value=f;o2.frequency.value=f*2;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.18*v,t+.012);g.gain.exponentialRampToValueAtTime(.05*v,t+.2);g.gain.exponentialRampToValueAtTime(.0001,t+Math.max(.25,dur));o.connect(g);o2.connect(g);g.connect(master);o.start(t);o2.start(t);o.stop(t+dur+.1);o2.stop(t+dur+.1)}async function tone(m,dur=.7,v=.75){if(!soundOn)return;let a=audio(),[r,f]=nearest(m);try{let b=await loadRoot(r,f),s=a.createBufferSource(),g=a.createGain();s.buffer=b;s.playbackRate.value=Math.pow(2,(m-r)/12);g.gain.value=.65*v;s.connect(g);g.connect(master);s.start();s.stop(a.currentTime+Math.min(b.duration,dur+1.4));activeSources.add(s);s.onended=()=>activeSources.delete(s)}catch(e){d('warn','sample_fallback',{error:String(e)});synth(m,dur,v)}}async function preload(){let u=new Map();for(const n of score.notes){let[r,f]=nearest(n.m);u.set(r,f)}Promise.all([...u].slice(0,14).map(([r,f])=>loadRoot(r,f).catch(()=>null))).then(()=>soundB.textContent='🎹 Grand piano')}
function frame(){if(!playing)return;beat=startBeat+(performance.now()-startTime)/1000/spb();if(beat>=score.total){beat=score.total;pause();updateScrub();draw();return}for(const n of score.notes)if(n.s>lastAudio+.0001&&n.s<=beat+.05)tone(n.m,n.d*spb(),n.v);lastAudio=beat;updateScrub();draw();raf=requestAnimationFrame(frame)}async function togglePlay(){if(playing){pause();return}await audio().resume();playing=true;playB.textContent='⏸ Pause';startBeat=beat;startTime=performance.now();lastAudio=beat-.001;raf=requestAnimationFrame(frame)}function pause(){playing=false;cancelAnimationFrame(raf);playB.textContent='▶ Play'}
let micStream=null,micSrc=null,ana=null,micTimer=0,micOn=false,buf=null,down=null,recent=[],lastMidi=null,lastAt=0,lastFreq=null,lastConf=null;const f2m=(f,a=440)=>69+12*Math.log2(f/a),m2f=(m,a=440)=>a*Math.pow(2,(m-69)/12);function mode(a){let M=new Map(),best=a[a.length-1],bc=0;for(const x of a){let c=(M.get(x)||0)+1;M.set(x,c);if(c>=bc){bc=c;best=x}}return best}function yin(b,sr,minF=27,maxF=4300){let n=b.length,min=Math.max(2,Math.floor(sr/maxF)),max=Math.min(Math.floor(sr/minF),Math.floor(n/2)-1),df=new Float32Array(max+1);for(let t=min;t<=max;t++){let sum=0,lim=Math.min(n-t,2600);for(let i=0;i<lim;i++){let q=b[i]-b[i+t];sum+=q*q}df[t]=sum/lim}let run=0,c=new Float32Array(max+1);for(let t=min;t<=max;t++){run+=df[t];c[t]=run?df[t]*((t-min+1)/run):1}let te=-1;for(let t=min+1;t<max;t++)if(c[t]<.16&&c[t]<=c[t-1]&&c[t]<=c[t+1]){te=t;while(te+1<max&&c[te+1]<c[te])te++;break}if(te<0){let best=1;for(let t=min;t<=max;t++)if(c[t]<best){best=c[t];te=t}if(te<0||best>.32)return null}let rt=te;if(te>min&&te<max){let x=c[te-1],y=c[te],z=c[te+1],den=2*y-z-x;if(Math.abs(den)>1e-8)rt=te+(z-x)/(2*den)}return{f:sr/rt,c:Math.max(0,1-c[te])}}function micLoop(){if(!micOn||!ana)return;ana.getFloatTimeDomainData(buf);let rms=0;for(let i=0,j=0;i<buf.length;i+=4,j++){let v=(buf[i]+buf[i+1]+buf[i+2]+buf[i+3])*.25;down[j]=v;rms+=v*v}rms=Math.sqrt(rms/down.length);if(rms>=+sens.value){let r=yin(down,AC.sampleRate/4);if(r&&r.c>=+conf.value)accept(r.f,r.c);else decay()}else decay();micTimer=setTimeout(micLoop,115)}function accept(f,c){let A=+a4.value,m=Math.round(f2m(f,A));if(m<21||m>108)return;recent.push(m);if(recent.length>7)recent.shift();m=mode(recent);if(recent.length>=3&&recent.filter(x=>x===m).length<3)return;lastAt=performance.now();lastFreq=f;lastConf=c;if(lastMidi!==null&&lastMidi!==m)keyEls.get(lastMidi)?.classList.remove('heard');lastMidi=m;keyEls.get(m)?.classList.add('heard');let cent=1200*Math.log2(f/m2f(m,A));heardB.textContent='Heard '+name(m)+' · '+f.toFixed(f<100?1:0)+'Hz';heardB.title='MIDI '+m+' · '+(c*100).toFixed(0)+'% · '+(cent>=0?'+':'')+cent.toFixed(0)+' cents';matchUpdate()}function decay(){if(performance.now()-lastAt>430)clearHeard()}function clearHeard(){if(lastMidi!==null)keyEls.get(lastMidi)?.classList.remove('heard');lastMidi=null;recent=[];heardB.textContent='Heard —';matchUpdate()}function matchUpdate(){matchB.classList.remove('good','bad');if(!target.size){matchB.textContent='Match —';return}if(lastMidi===null){matchB.textContent='Match listening';return}if(target.has(lastMidi)){matchB.textContent='Match correct';matchB.classList.add('good');return}let near=[...target].reduce((a,b)=>Math.abs(b-lastMidi)<Math.abs(a-lastMidi)?b:a);matchB.textContent=lastMidi<near?'Match too low':'Match too high';matchB.classList.add('bad')}async function startMic(){if(!navigator.mediaDevices?.getUserMedia){setStatus('Microphone requires HTTPS and a modern browser.',true);return}try{audio();micStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false,channelCount:1}});micSrc=AC.createMediaStreamSource(micStream);ana=AC.createAnalyser();ana.fftSize=16384;ana.smoothingTimeConstant=0;micSrc.connect(ana);buf=new Float32Array(ana.fftSize);down=new Float32Array(ana.fftSize/4);micOn=true;listenB.classList.add('listening');listenB.textContent='■ Stop listen';micB.textContent='Mic listening';micB.classList.add('live');d('info','mic_started',{rate:AC.sampleRate});micLoop()}catch(e){d('error','mic_failed',{error:String(e)});setStatus('Microphone failed. Check permission/HTTPS, then copy diagnostics.',true)}}function stopMic(){micOn=false;clearTimeout(micTimer);try{micSrc?.disconnect()}catch(_){}micStream?.getTracks().forEach(t=>t.stop());micStream=micSrc=ana=null;listenB.classList.remove('listening');listenB.textContent='🎤 Listen';micB.textContent='Mic off';micB.classList.remove('live');clearHeard()}
let dragState=null;drag.addEventListener('pointerdown',e=>{if(document.body.classList.contains('focus'))return;let tr=trainer.getBoundingClientRect(),wr=workspace.getBoundingClientRect();dragState={id:e.pointerId,dx:e.clientX-tr.left,dy:e.clientY-tr.top};drag.setPointerCapture(e.pointerId)});drag.addEventListener('pointermove',e=>{if(!dragState||dragState.id!==e.pointerId)return;let wr=workspace.getBoundingClientRect(),tr=trainer.getBoundingClientRect(),l=clamp(e.clientX-wr.left-dragState.dx,0,Math.max(0,wr.width-tr.width)),t=clamp(e.clientY-wr.top-dragState.dy,0,Math.max(0,wr.height-tr.height));trainer.style.left=l+'px';trainer.style.top=t+'px'});drag.addEventListener('pointerup',()=>dragState=null);
let rs=null;document.querySelectorAll('.rz').forEach(z=>{z.addEventListener('pointerdown',e=>{if(document.body.classList.contains('focus'))return;e.preventDefault();let tr=trainer.getBoundingClientRect(),wr=workspace.getBoundingClientRect();rs={id:e.pointerId,d:z.dataset.d,sx:e.clientX,sy:e.clientY,x:tr.left-wr.left,y:tr.top-wr.top,w:tr.width,h:tr.height};z.setPointerCapture(e.pointerId)});z.addEventListener('pointermove',e=>{if(!rs||rs.id!==e.pointerId)return;let wr=workspace.getBoundingClientRect(),dx=e.clientX-rs.sx,dy=e.clientY-rs.sy,l=rs.x,t=rs.y,w=rs.w,h=rs.h,minW=Math.min(300,wr.width),minH=Math.min(300,wr.height);if(rs.d.includes('e'))w=clamp(rs.w+dx,minW,wr.width-rs.x);if(rs.d.includes('w')){let q=clamp(dx,-rs.x,rs.w-minW);l=rs.x+q;w=rs.w-q}if(rs.d.includes('s'))h=clamp(rs.h+dy,minH,wr.height-rs.y);if(rs.d.includes('n')){let q=clamp(dy,-rs.y,rs.h-minH);t=rs.y+q;h=rs.h-q}Object.assign(trainer.style,{left:l+'px',top:t+'px',width:w+'px',height:h+'px'});resize()});z.addEventListener('pointerup',()=>rs=null);z.addEventListener('pointercancel',()=>rs=null)});
function captureCal(){let r=trainer.getBoundingClientRect(),k=keyboard.getBoundingClientRect();document.documentElement.style.setProperty('--calLeft',r.left+'px');document.documentElement.style.setProperty('--calWidth',r.width+'px');document.documentElement.style.setProperty('--calKbH',k.height+'px')}const small=()=>Math.min(screen.width||innerWidth,screen.height||innerHeight)<=900||matchMedia('(pointer:coarse) and (max-width:1000px)').matches,portrait=()=>innerHeight>innerWidth;async function enterFull(){captureCal();document.body.classList.add('focus');try{if(workspace.requestFullscreen&&!document.fullscreenElement)await workspace.requestFullscreen()}catch(_){}let locked=false;if(small()&&portrait())try{if(screen.orientation?.lock){await screen.orientation.lock('landscape');locked=true}}catch(_){}await new Promise(r=>setTimeout(r,120));document.body.classList.toggle('force-landscape',small()&&portrait()&&!locked);resize()}async function exitFull(){document.body.classList.remove('force-landscape');try{screen.orientation?.unlock?.()}catch(_){}try{if(document.fullscreenElement)await document.exitFullscreen()}catch(_){}document.body.classList.remove('focus');resize()}
function fit(){if(!document.body.classList.contains('focus'))workspace.style.height=Math.max(430,innerHeight-workspace.getBoundingClientRect().top)+'px';resize()}window.addEventListener('resize',fit);new ResizeObserver(resize).observe(trainer);document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&document.body.classList.contains('focus')){document.body.classList.remove('focus','force-landscape');resize()}});
playB.onclick=togglePlay;restartB.onclick=()=>{pause();seek(0)};tempo.oninput=()=>{$('tempoV').textContent=tempo.value;if(playing){startBeat=beat;startTime=performance.now()}updateScrub()};lead.oninput=()=>{$('leadV').textContent=(+lead.value).toFixed(1);draw()};view.onchange=()=>{updateRange();buildKeys();draw()};scrub.oninput=()=>seek(scrub.value);file.onchange=async()=>{let f=file.files[0];if(!f)return;try{apply(parseXML(await f.text(),f.name),f.name)}catch(e){setStatus('Could not read '+f.name+': '+e.message,true)}};soundB.onclick=()=>{soundOn=!soundOn;soundB.textContent=soundOn?'🎹 Grand piano':'🔇 Sound off';if(!soundOn){activeSources.forEach(s=>{try{s.stop()}catch(_){}});activeSources.clear()}};testB.onclick=async()=>{soundOn=true;audio();await tone(60,1.1,.9);setStatus('Tested middle C. If silent, copy diagnostics.')};listenB.onclick=()=>micOn?stopMic():startMic();sens.oninput=()=>{$('sensV').textContent=(+sens.value).toFixed(3).replace(/^0/,'')};conf.oninput=()=>{$('confV').textContent=(+conf.value).toFixed(2).replace(/^0/,'')};a4.oninput=()=>{$('a4V').textContent=(+a4.value).toFixed((+a4.value)%1?1:0);if(lastFreq&&lastConf)accept(lastFreq,lastConf)};fullB.onclick=enterFull;closeB.onclick=exitFull;$('reset').onclick=()=>{Object.assign(trainer.style,{left:'4%',top:'22px',width:'92%',height:'86%'});resize()};diagB.onclick=async()=>{d('info','report_requested',{audio:AC?AC.state:'none',mic:micOn,lastMidi,score:score.title});await flush();try{let r=await fetch(location.pathname+'?diag=report&session='+encodeURIComponent(S),{cache:'no-store'}),t=await r.text();try{await navigator.clipboard.writeText(t);setStatus('Diagnostics copied — paste them into chat.')}catch(_){prompt('Copy diagnostics:',t)}}catch(e){setStatus('Diagnostic report failed: '+e.message,true)}};keyboard.addEventListener('pointerdown',async e=>{let k=e.target.closest('.key');if(!k)return;let m=+k.dataset.m;audio();tone(m,.7,.8)});window.addEventListener('beforeunload',()=>{if(micOn)stopMic()});
fit();loadDemo();d('info','page_ready',{ua:navigator.userAgent,viewport:[innerWidth,innerHeight],secure:window.isSecureContext});
})();
